//go:build s390x

package floats

// z/Architecture vector-facility FMA kernels for float64, generated by
// go-asmgen (kernels_s390x_gen.go) into kernels_s390x.s. The vector facility is
// the z13 baseline, so these are used unconditionally.
//
// All six kernels (Dot, Sum, SumSqDiff in float64 and float32) keep EIGHT
// independent accumulators. The earlier single-accumulator VFMADB Dot lost to
// the plain Go loop on z15 (0.56×) and the single-accumulator Sum ran one
// latency-bound chain; with eight chains, measured on z17 (linux1, one core,
// steal 0), old -> new: f64 Dot n=1000 386 -> 191 ns (2.0×), Sum 624 -> 106 ns
// (5.9×), Distance 644 -> 204 ns (3.2×); float32 Dot 2849 -> 105 ns (27×), Sum
// 2898 -> 61 ns (47×), because float32 used the lane-blocked scalar reference
// before. The float32 kernels need the vector-enhancements facility 1 (z14: the
// .SB ops are emitted as encoded words, see the generator) and are gated on
// hasVXE; the lane-blocked reference is the fallback. Below vxMin64 float64
// uses the plain loops.
//
//go:noescape
func sumVX(a []float64) float64

//go:noescape
func sumSqDiffVX(a, b []float64) float64

//go:noescape
func dotVX(a, b []float64) float64

//go:noescape
func dot32VX(a, b []float32) float32

//go:noescape
func sum32VX(a []float32) float32

//go:noescape
func sumSqDiff32VX(a, b []float32) float32

// vxMin64 is the shortest float64 reduction sent to the VX kernels: below it the
// kernel's setup (eight zeroed accumulators, the fold) costs 1-3 ns more than
// the plain loop (z17, linux1: Dot n=3 3.8 vs 6.4 ns, n=8 5.4 vs 8.1 ns); from
// n=16 the kernel ties and from n=32 it wins 1.4x and more. Under the
// threshold a four-accumulator Go loop (smallred.go) replaces the plain loop:
// z17, n=8 Dot 7.5 -> 6.2 ns, n=12 11.8 -> 7.4 ns; at n=16 the kernel (10.4 ns)
// still beats it (11.2 ns), so the threshold stays.
const vxMin64 = 16

func dot(a, b []float64) float64 {
	if len(a) >= vxMin64 {
		return dotVX(a, b)
	}
	if len(a) >= 4 {
		return dotSmall(a, b)
	}
	var s float64
	for i := range a {
		s += a[i] * b[i]
	}
	return s
}

func sum(a []float64) float64 {
	if len(a) >= vxMin64 {
		return sumVX(a)
	}
	if len(a) >= 4 {
		return sumSmall(a)
	}
	var s float64
	for _, v := range a {
		s += v
	}
	return s
}

func sumSqDiff(a, b []float64) float64 {
	if len(a) >= vxMin64 {
		return sumSqDiffVX(a, b)
	}
	if len(a) >= 4 {
		return sumSqDiffSmall(a, b)
	}
	var s float64
	for i := range a {
		d := a[i] - b[i]
		s += d * d
	}
	return s
}

// axpyVX is y[i] = fma(alpha, x[i], y[i]) with VFMADB (one rounding, so it is
// bit-identical to axpyRef). It replaces the portable loop: measured on real z17
// silicon (linuxone, 2026-11-22) the loop was 1.5x slower than this shape of
// kernel from 64 elements up.
//
//go:noescape
func axpyVX(alpha float64, x, y []float64)

func axpy(alpha float64, x, y []float64) { axpyVX(alpha, x, y) }

func dot32(a, b []float32) float32 {
	if hasVXE {
		return dot32VX(a, b)
	}
	return dotLanes32(a, b)
}

func sum32(a []float32) float32 {
	if hasVXE {
		return sum32VX(a)
	}
	return sumLanes32(a)
}

func sumSqDiff32(a, b []float32) float32 {
	if hasVXE {
		return sumSqDiff32VX(a, b)
	}
	return sumSqDiffLanes32(a, b)
}
